<script>
  import { onMount, tick } from 'svelte';
  let csrf = '', password = '', loggedIn = false, error = '', busy = false;
  let page = 'Overview', snapshot = null, history = [], audit = [], stream;
  let network = '', reason = '', kind = 'block', duration = '600', acknowledged = false;
  let management = [], thresholds = {}, resolution = 'minute', range = '86400';
  let selectedIP = '', lookupIP = '', detail = null, detailError = '', detailBusy = false;
  let detailLimits = {minute_days:7,hourly_days:90,row_limit:1000000};
  let detailPanel, detailPaged = false;
  let detailRange = '86400', detailProtocol = '', detailPort = '', detailTo = 0, detailEvents = [], detailRequest = 0;
  const pages = ['Overview', 'Traffic', 'History', 'Detections', 'Firewall', 'Health'];
  const fmt = (n = 0) => new Intl.NumberFormat('en', { notation: n >= 1000000 ? 'compact' : 'standard', maximumFractionDigits: 1 }).format(n);
  const bytes = (n = 0) => n >= 1e9 ? `${(n/1e9).toFixed(2)} GB` : n >= 1e6 ? `${(n/1e6).toFixed(1)} MB` : `${(n/1000).toFixed(1)} kB`;
  const time = (s) => s ? new Date(s * 1000).toLocaleString() : '—';
  const protocol = (p) => ({6:'TCP',17:'UDP',1:'ICMP',58:'ICMPv6'})[p] || `IP ${p}`;
  async function api(path, method = 'GET', data) {
    const response = await fetch(`/api/v1${path}`, { method, headers: {'Content-Type':'application/json', ...(csrf ? {'X-CSRF-Token':csrf} : {})}, ...(data !== undefined ? {body:JSON.stringify(data)} : {}) });
    const result = response.status === 204 ? null : await response.json();
    if (!response.ok) { if (response.status === 401 && path !== '/auth/login') {loggedIn=false;stream?.close();} throw new Error(result?.error || `Request failed (${response.status})`); }
    return result;
  }
  async function loadSession() {
    const session = await api('/auth/session'); csrf=session.csrf;management=session.management_allowlist;thresholds=session.thresholds;detailLimits=session.detail_limits||detailLimits;
    snapshot=await api('/snapshot');loggedIn=true;stream?.close();stream=new EventSource('/api/v1/stream');
    stream.addEventListener('snapshot', e => snapshot=JSON.parse(e.data));
    stream.addEventListener('resync', async () => {try {snapshot=await api('/snapshot');}catch(e){error=e.message;}});
    stream.addEventListener('session_expired', () => {loggedIn=false;stream.close();});
    stream.onerror=()=>{ if (loggedIn) {error='Live stream interrupted. Reconnecting…';api('/auth/session').catch(e=>error=e.message);} };
    stream.onopen=()=>{if(error.startsWith('Live stream'))error='';};
  }
  async function login() {busy=true;error='';try {const s=await api('/auth/login','POST',{password});csrf=s.csrf;password='';await loadSession();}catch(e){error=e.message;}finally{busy=false;}}
  async function logout() {try{await api('/auth/logout','POST');}catch(e){error=e.message;}stream?.close();loggedIn=false;csrf='';}
  async function navigate(p) {page=p;error='';try{if(p==='History')await loadHistory();if(p==='Detections')audit=await api('/events');}catch(e){error=e.message;}}
  async function loadHistory() {const to=Math.floor(Date.now()/1000);history=await api(`/history?resolution=${resolution}&from=${to-Number(range)}&to=${to}`);}
  async function showSource(ip) {
    selectedIP=ip.trim();lookupIP=selectedIP;page='Traffic';detail=null;detailEvents=[];
    const source=selectedIP;
    await tick();detailPanel?.scrollIntoView({behavior:'smooth',block:'start'});
    await loadSource();
    try {const events=await api(`/events?ip=${encodeURIComponent(source)}`);if(selectedIP===source)detailEvents=events;}catch(e){if(selectedIP===source)detailError=e.message;}
  }
  async function loadSource(more=false) {
    if(!selectedIP||!loggedIn)return;
    const request=++detailRequest;detailBusy=true;detailError='';
    detailPaged=more;
    if(!more)detailTo=Math.floor(Date.now()/1000);
    const params=new URLSearchParams({from:String(detailTo-Number(detailRange)),to:String(detailTo),resolution:Number(detailRange)>604800?'hour':'minute',limit:'100'});
    if(detailProtocol)params.set('protocol',detailProtocol);
    if(detailPort!==''&&detailPort!==undefined)params.set('port',String(detailPort));
    if(more&&detail?.next_cursor)params.set('cursor',detail.next_cursor);
    try {
      const result=await api(`/sources/${encodeURIComponent(selectedIP)}/traffic?${params}`);
      if(request===detailRequest)detail=more?{...result,rows:[...detail.rows,...result.rows]}:result;
    }catch(e){if(request===detailRequest)detailError=e.message;}finally{if(request===detailRequest)detailBusy=false;}
  }
  async function mutate(path,method,data) {busy=true;error='';try{await api(path,method,data);snapshot=await api('/snapshot');}catch(e){error=e.message;}finally{busy=false;}}
  async function addRule() {
    let cidr=network.trim();if(!cidr.includes('/'))cidr += cidr.includes(':') ? '/128' : '/32';
    await mutate('/rules','POST',{network:cidr,kind,reason,seconds:duration==='permanent'?null:Number(duration)});
    if(!error){network='';reason='';}
  }
  $: chartMax=Math.max(1,...history.map(h=>h.totals.packets));
  $: chartPoints=history.map((h,i)=>`${history.length<2?0:i/(history.length-1)*1000},${150-h.totals.packets/chartMax*140}`).join(' ');
  $: other=Math.max(0,(snapshot?.totals.packets||0)-(snapshot?.sources||[]).reduce((n,s)=>n+s.packets,0));
  onMount(()=>{loadSession().catch(()=>{});const refresh=setInterval(()=>{if(loggedIn&&page==='Traffic'&&selectedIP&&!detailBusy&&!detailPaged&&!detail?.next_cursor)loadSource();},5000);return()=>{stream?.close();clearInterval(refresh);};});
</script>

{#if !loggedIn}
  <main class="login"><div class="login-card"><div class="brand"><span class="mark">e</span> einblick</div><span class="eyebrow">NETWORK OBSERVABILITY</span><h1>A clear view<br>of your network.</h1><p>Live traffic, security signals, and control.<br>Independently hosted on your server.</p>
    <form onsubmit={(e)=>{e.preventDefault();login();}}><label for="password">Administrator password</label><input id="password" type="password" bind:value={password} autocomplete="current-password" required minlength="12"><button class="primary" disabled={busy}>{busy?'Signing in…':'Sign in →'}</button></form>
    {#if error}<p class="error" role="alert">{error}</p>{/if}<small>Access through your configured HTTPS proxy.</small></div>
    <div class="login-art" aria-hidden="true"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><div class="art-label">VISIBILITY AT THE EDGE</div><div class="art-dot"></div></div>
  </main>
{:else}
  <div class="shell"><aside><div class="brand"><span class="mark">e</span> einblick</div><div class="eyebrow side-label">WORKSPACE / THIS SERVER</div><nav>{#each pages as p,i}<button class:active={page===p} onclick={()=>navigate(p)}><span class="nav-icon">{['◈','≋','◷','⚑','⊞','⌁'][i]}</span>{p}{#if p==='Detections'&&snapshot?.detections.length}<span class="count">{snapshot.detections.length}</span>{/if}</button>{/each}</nav><div class="side-bottom"><span class="status-dot"></span> Independently hosted <button onclick={logout}>Sign out ↗</button></div></aside>
    <main class="content"><header><div><span class="eyebrow">NETWORK / {page.toUpperCase()}</span><h1>{page==='Overview'?'Your network, at a glance.':page==='Firewall'?'Control incoming traffic.':page==='Detections'?'Signals worth investigating.':page==='History'?'Traffic over time.':page==='Health'?'System health.':'Who’s reaching your server.'}</h1></div><div class="live"><span class="status-dot" class:warning={!snapshot?.health.telemetry_complete}></span>{snapshot?.health.backend.startsWith('mock')?'Demo traffic':'Live ingress'}<small>{time(snapshot?.at)}</small></div></header>
    {#if error}<div class="error banner" role="alert">{error}<button onclick={()=>error=''} aria-label="Dismiss error">×</button></div>{/if}
    {#if snapshot?.health.backend.startsWith('mock')}<div class="notice">DEMO MODE <span>Synthetic traffic. Firewall changes are simulated.</span></div>{/if}
    {#if snapshot&&!snapshot.health.telemetry_complete}<div class="notice amber">INCOMPLETE TELEMETRY <span>{snapshot.health.detection_complete?'Detection evidence is complete.':'New automatic bans are suspended.'} {snapshot.health.reasons?.join(' / ')}</span></div>{/if}
    {#if snapshot}
      {#if page==='Overview'}
        <div class="cards"><article><span class="eyebrow">OBSERVED PACKETS</span><strong>{fmt(snapshot.totals.packets)}</strong><small>{fmt(snapshot.rate.packets)} packets / latest interval</small><div class="mini-line"></div></article><article><span class="eyebrow">INCOMING VOLUME</span><strong>{bytes(snapshot.totals.bytes)}</strong><small>{bytes(snapshot.rate.bytes)} / latest interval</small><div class="mini-line blue"></div></article><article><span class="eyebrow">BLOCKED PACKETS</span><strong>{fmt(snapshot.totals.dropped)}</strong><small>{fmt(snapshot.totals.passed)} passed</small><div class="mini-line amber-line"></div></article><article><span class="eyebrow">ENFORCEMENT</span><strong class="mode-text">{snapshot.automatic?'Automatic':snapshot.blocking?'Manual':'Observe'}</strong><small>{snapshot.rules.filter(r=>r.applied&&r.kind==='block').length} applied block rules</small><div class="mini-line gray"></div></article></div>
        <div class="grid"><section class="panel"><div class="panel-title"><h2>Top sources</h2><button class="text" onclick={()=>navigate('Traffic')}>View traffic ↗</button></div><table><thead><tr><th>Source</th><th>Packets</th><th>Volume</th></tr></thead><tbody>{#each snapshot.sources.slice(0,8) as s}<tr><td><button class="text mono ip-link" onclick={()=>showSource(s.ip)}>{s.ip}</button></td><td>{fmt(s.packets)}</td><td>{bytes(s.bytes)}</td></tr>{/each}{#if !snapshot.sources.length}<tr><td colspan="3" class="empty">Waiting for incoming traffic.</td></tr>{/if}</tbody></table><footer class="panel-foot">Current tracked sources · other / untracked: {fmt(other)} packets</footer></section>
        <section class="panel"><div class="panel-title"><h2>Recent signals</h2><button class="text" onclick={()=>navigate('Detections')}>All events ↗</button></div>{#each [...snapshot.detections].reverse().slice(0,5) as d}<div class="signal"><span class="signal-icon">!</span><div><b>{d.kind.replaceAll('_',' ')}</b><span class="mono">{d.ip}</span><small>{d.evidence}</small></div><small>{new Date(d.at*1000).toLocaleTimeString()}</small></div>{/each}{#if !snapshot.detections.length}<div class="empty roomy"><span class="quiet-icon">◈</span>No recent detections.<small>Thresholds are evaluated as traffic arrives.</small></div>{/if}</section></div>
        <div class="footnote">Ingress packet metadata · SYNs are attempts, including retransmissions · counters since process start</div>
      {:else if page==='Traffic'}
        <div class="grid"><section class="panel"><div class="panel-title"><h2>Source addresses</h2><span class="tag">TOP 100</span></div><div class="table-scroll"><table><thead><tr><th>Address</th><th>Packets</th><th>Bytes</th><th>SYN attempts</th></tr></thead><tbody>{#each snapshot.sources as s}<tr><td><button class="text mono ip-link" onclick={()=>showSource(s.ip)}>{s.ip}</button></td><td>{fmt(s.packets)}</td><td>{bytes(s.bytes)}</td><td>{fmt(s.syns)}</td></tr>{/each}</tbody></table></div><footer class="panel-foot">Other / untracked: {fmt(other)} packets. Source detail is bounded.</footer></section><section class="panel"><div class="panel-title"><h2>Destination ports & protocols</h2></div><div class="table-scroll"><table><thead><tr><th>Protocol</th><th>Port</th><th>Packets</th></tr></thead><tbody>{#each snapshot.ports as p}<tr><td>{protocol(p.protocol)}</td><td class="mono">{p.port||'unparsed / none'}</td><td>{fmt(p.packets)}</td></tr>{/each}</tbody></table></div></section></div>
        <section class="panel ip-detail" bind:this={detailPanel}>
          <div class="panel-title"><h2>Inspect a source IP</h2><form class="ip-lookup" onsubmit={e=>{e.preventDefault();showSource(lookupIP);}}><label class="sr-only" for="ip-lookup">Source IP address</label><input id="ip-lookup" bind:value={lookupIP} placeholder="IPv4 or IPv6 address" required><button disabled={detailBusy}>Inspect →</button></form></div>
          {#if selectedIP}
            <div class="detail-toolbar"><div><strong class="mono">{selectedIP}</strong><small>Ingress before host firewall/NAT · passed means passed by Einblick.</small></div><div class="filters"><label>Range<select bind:value={detailRange} onchange={()=>loadSource()}><option value="3600">Last hour</option><option value="86400">24 hours</option><option value="604800">7 days</option><option value="7776000">90 days</option></select></label><label>Protocol<select bind:value={detailProtocol} onchange={()=>loadSource()}><option value="">All</option><option value="6">TCP</option><option value="17">UDP</option><option value="1">ICMP</option><option value="58">ICMPv6</option></select></label><label>Destination port<input type="number" min="0" max="65535" bind:value={detailPort} onchange={()=>loadSource()} placeholder="All"></label><button disabled={detailBusy} onclick={()=>loadSource()}>Refresh</button></div></div>
            {#if detailError}<p class="error detail-message" role="alert">{detailError}</p>{/if}
            {#if detail}
              {#each detail.warnings as warning}<div class="notice amber detail-message">{warning}</div>{/each}
              <div class="table-scroll"><table><thead><tr><th>Destination / interface</th><th>Protocol / port</th><th>Packets / volume</th><th>TCP indicators</th><th>Passed / dropped</th><th>First / last seen</th></tr></thead><tbody>{#each detail.rows as row}<tr><td class="mono">{row.destination}<small class="actor">{row.interface}</small></td><td>{protocol(row.protocol)} / {row.port===null?'unknown / none':row.port}<small class="actor">Source ports: {row.source_ports.join(', ')||'none'}{row.source_ports_truncated?' · sample truncated':''}</small></td><td>{fmt(row.packets)}<small class="actor">{bytes(row.bytes)}</small></td><td>{fmt(row.syns)} SYN attempts<small class="actor">{fmt(row.syn_acks)} SYN/ACK · {fmt(row.resets)} RST</small></td><td>{fmt(row.passed)} passed<small class="actor">{fmt(row.dropped)} dropped by Einblick</small></td><td>{time(row.first_seen)}<small class="actor">{time(row.last_seen)}</small></td></tr>{/each}{#if !detail.rows.length}<tr><td colspan="6" class="empty">No retained matching detail for this IP and range. Check coverage messages above.</td></tr>{/if}</tbody></table></div>
              <footer class="panel-foot">Recorded since {time(detail.capture_started)} · {fmt(detail.stored_rows)} / {fmt(detailLimits.row_limit)} stored detail rows<small class="actor">Available persisted buckets: {time(detail.available_from)} – {time(detail.available_to)}</small>{#if detail.next_cursor}<button disabled={detailBusy} onclick={()=>loadSource(true)}>Load more</button>{/if}</footer>
            {:else if detailBusy}<div class="empty roomy">Loading source detail…</div>{/if}
            {#if detailEvents.length}<div class="panel-title"><h2>Detection events for this IP</h2></div>{#each detailEvents.slice(0,10) as event}<div class="signal"><span class="signal-icon">!</span><div><b>{event.detail.kind?.replaceAll('_',' ')||event.kind}</b><small>{event.detail.evidence||event.kind}</small></div><small>{time(event.at)}</small></div>{/each}{/if}
            <p class="detail-message footnote">SYNs indicate TCP connection attempts, including retransmissions. These counters do not confirm successful connections, URLs, or logins. Minute detail: {detailLimits.minute_days} days; hourly detail: {detailLimits.hourly_days} days, subject to the storage cap.</p>
          {:else}<div class="empty roomy">Select an IP above or enter an address to see its ports and protocols.</div>{/if}
        </section>
      {:else if page==='History'}
        <section class="panel"><div class="panel-title"><h2>Observed packets</h2><div class="filters"><label>Resolution <select bind:value={resolution} onchange={()=>loadHistory().catch(e=>error=e.message)}><option value="minute">Minute</option><option value="hour">Hour</option></select></label><label>Range <select bind:value={range} onchange={()=>loadHistory().catch(e=>error=e.message)}><option value="86400">24 hours</option><option value="604800">7 days</option><option value="7776000">90 days</option></select></label></div></div>
          {#if history.length}<div class="chart"><div class="chart-label">{fmt(chartMax)} packets / {resolution}</div><svg viewBox="0 0 1000 160" preserveAspectRatio="none" role="img" aria-label="Historical observed packet counts"><line x1="0" x2="1000" y1="150" y2="150" stroke="#dce5e7"/><polyline points={chartPoints} fill="none" stroke="#159b89" stroke-width="2" vector-effect="non-scaling-stroke"/></svg><div class="chart-axis"><span>{time(history[0].at)}</span><span>{time(history.at(-1).at)}</span></div></div>{:else}<div class="empty roomy">No aggregates in this range.<small>The first partial minute is saved at the next minute boundary.</small></div>{/if}
          <div class="table-scroll"><table><thead><tr><th>Time</th><th>Observed</th><th>Volume</th><th>Blocked</th><th>Evidence</th></tr></thead><tbody>{#each [...history].reverse() as h}<tr><td>{time(h.at)}</td><td>{fmt(h.totals.packets)}</td><td>{bytes(h.totals.bytes)}</td><td>{fmt(h.totals.dropped)}</td><td><span class="tag" class:amber={ !h.complete }>{h.complete?'Complete':'Incomplete'}</span></td></tr>{/each}</tbody></table></div>
        </section><p class="footnote">Minute data: 7 days · hourly data: 90 days by default. Queries return at most 1,000 buckets. Source detail is approximate top-N.</p>
      {:else if page==='Detections'}
        <section class="panel"><div class="panel-title"><h2>Security & enforcement audit</h2><button class="text" onclick={()=>api('/events').then(v=>audit=v).catch(e=>error=e.message)}>Refresh ↻</button></div>{#each audit as e}<div class="audit"><span class="tag">{e.kind.replaceAll('_',' ')}</span><time>{time(e.at)}</time><pre>{JSON.stringify(e.detail,null,2)}</pre></div>{/each}{#if !audit.length}<div class="empty roomy">No events recorded yet.</div>{/if}<footer class="panel-foot"><button disabled={!audit.length} onclick={()=>api(`/events?before=${audit.at(-1)?.id}`).then(v=>audit=[...audit,...v]).catch(e=>error=e.message)}>Load older events</button></footer></section>
      {:else if page==='Firewall'}
        <section class="panel settings"><div><h2>Enforcement mode</h2><p>Manual rules apply when blocking is enabled. Automatic bans expire after {thresholds.ban_seconds||600} seconds.</p><div class="mode-buttons"><button disabled={busy} class:selected={!snapshot.blocking} onclick={()=>mutate('/mode','POST',{automatic:false,blocking:false,acknowledged:false})}>Observe</button><button disabled={busy} class:selected={snapshot.blocking&&!snapshot.automatic} onclick={()=>mutate('/mode','POST',{automatic:false,blocking:true,acknowledged:false})}>Manual</button><button disabled={busy||!management.length||!acknowledged} class:selected={snapshot.automatic} onclick={()=>mutate('/mode','POST',{automatic:true,blocking:true,acknowledged})}>Automatic IP bans</button></div><label class="checkbox"><input type="checkbox" bind:checked={acknowledged}> I reviewed observe-mode evidence and thresholds.</label><small>Protected management ranges: {management.length?management.join(', '):'Configure management_allowlist before enabling automatic bans.'}</small></div><button class="danger" disabled={busy} onclick={()=>mutate('/emergency-disable','POST')}>Disable blocking now</button></section>
        <section class="panel"><div class="panel-title"><h2>Add a rule</h2><span class="tag">ALLOWLIST ALWAYS WINS</span></div><form class="rule-form" onsubmit={e=>{e.preventDefault();addRule();}}><label>IP address or CIDR<input bind:value={network} placeholder="192.0.2.1 or 2001:db8::/32" required></label><label>Action<select bind:value={kind}><option value="block">Block</option><option value="allow">Allow</option></select></label><label>Duration<select bind:value={duration}><option value="600">10 minutes</option><option value="3600">1 hour</option><option value="86400">1 day</option><option value="permanent">Permanent</option></select></label><label>Reason<input bind:value={reason} maxlength="512" required placeholder="Why this rule is needed"></label><button class="primary" disabled={busy}>Add rule</button></form><p class="panel-foot">Adding a block rule enables manual blocking. CIDR and permanent bans are manual actions.</p></section>
        <section class="panel"><div class="panel-title"><h2>Rules</h2></div><div class="table-scroll"><table><thead><tr><th>Network</th><th>Action</th><th>Reason</th><th>Expires</th><th>Status</th><th></th></tr></thead><tbody>{#each snapshot.rules as r}<tr><td class="mono">{r.network}</td><td><span class="tag" class:amber={r.kind==='block'}>{r.kind}</span></td><td>{r.reason}<small class="actor">{r.actor}</small></td><td>{r.expires?time(r.expires):'Permanent'}</td><td title={r.error||''}>{r.error?'Failed':!r.enabled?'Removed':r.expires&&r.expires<=snapshot.at?'Expired':r.applied?'Applied':'Inactive / pending'}</td><td><button class="text" disabled={busy||!r.enabled} onclick={()=>mutate(`/rules/${r.id}`,'DELETE')}>Remove</button></td></tr>{/each}{#if !snapshot.rules.length}<tr><td class="empty" colspan="6">No rules configured.</td></tr>{/if}</tbody></table></div></section>
      {:else if page==='Health'}
        <div class="grid"><section class="panel"><div class="panel-title"><h2>Runtime</h2></div><dl><dt>Backend</dt><dd>{snapshot.health.backend}</dd><dt>Interfaces</dt><dd>{snapshot.health.attachments.join(', ')||'Synthetic input'}</dd><dt>Storage</dt><dd>{snapshot.health.storage_ok?'Healthy':'Failed · automatic bans suspended'}</dd><dt>Enforcement</dt><dd>{snapshot.health.enforcement_ok?'Synchronized':'Failed · reconciliation pending'}</dd><dt>Detection evidence</dt><dd>{snapshot.health.detection_complete?'Complete latest interval':'Incomplete / new automatic bans suspended'}</dd><dt>Traffic detail</dt><dd>{snapshot.health.detail_complete?'Complete latest interval':'Incomplete latest interval'}</dd><dt>Last observation</dt><dd>{time(snapshot.health.last_tick)}</dd></dl>{#if snapshot.health.last_error}<div class="error banner">{snapshot.health.last_error}</div>{/if}</section><section class="panel"><div class="panel-title"><h2>Telemetry limits</h2></div><dl><dt>Parsing limitations</dt><dd>{fmt(snapshot.totals.parse_limits)}</dd><dt>SYN event loss</dt><dd>{fmt(snapshot.totals.event_loss)}</dd><dt>Map capacity misses</dt><dd>{fmt(snapshot.totals.map_full)}</dd><dt>Source / port / IP detail misses</dt><dd>{fmt(snapshot.totals.source_misses)} / {fmt(snapshot.totals.port_misses)} / {fmt(snapshot.totals.association_misses)}</dd><dt>Port scan threshold</dt><dd>{thresholds.scan_ports} distinct ports / 60s</dd><dt>SYN flood threshold</dt><dd>{fmt(thresholds.syns_10s)} SYNs / 10s</dd><dt>Packet flood threshold</dt><dd>{fmt(thresholds.flood_pps)} packets/s for 3s</dd></dl></section></div><section class="panel"><div class="panel-title"><h2>Tracking map occupancy</h2></div><table><thead><tr><th>Map</th><th>Collected entries</th><th>Capacity</th></tr></thead><tbody>{#each snapshot.health.maps||[] as map}<tr><td>{map.name}</td><td>{fmt(map.used)}</td><td>{fmt(map.capacity)}</td></tr>{/each}</tbody></table></section><p class="footnote">Unsupported transport headers are passed and counted. Extractable source addresses still participate in rules. XDP detaches when the process exits; active persisted rules restore on restart.</p>
      {/if}
    {/if}
    </main>
  </div>
{/if}

<style>
  .ip-link{padding:0;text-align:left;text-decoration:underline;text-underline-offset:3px}.ip-detail{margin-top:22px}.ip-lookup{display:flex;gap:8px;flex-wrap:wrap}.ip-lookup input{width:250px}.detail-toolbar{padding:20px 24px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap}.detail-toolbar small{display:block;margin-top:8px}.detail-toolbar input{width:90px;padding:7px;font-size:11px}.detail-toolbar .filters{align-items:end;flex-wrap:wrap}.detail-message{margin:16px 24px}.panel-foot button{margin-left:15px}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
